prts.feedbackvariables:
/* Input verification - Check whether the counter example input is a matrix. Note that if the input is not a matrix, the dimension verification always fails. It is important that the PRT stops if the input is not a matrix. */
 isInputMatrix : matrixp(ansMatrix);
M : if isInputMatrix then ansMatrix else ident(1);
n:first(matrix_size(M));
r:second(matrix_size(M));
isInputSquare:is(n=r);
safe_input:(isInputMatrix and isInputSquare);
okayInput:(ansTF or (isInputMatrix and isInputSquare));

/* Check whether the example supplied by the student is indeed correct. If the student answered that the statement is true, then the variable exampleChecksOut is automatically set to be false. */

alpha : if safe_input then ansMatrix[1][1] else -1; /* don't access input unless it's a matrix */
isScalar:is(ansMatrix = diagmatrix(n,alpha));
nonZero:not(is(ansMatrix = diagmatrix(n,0)));
notIdent:not(is(ansMatrix = diagmatrix(n,1)));
exampleChecksOut : if ansTF then false else is (isScalar and nonZero and notIdent);
